defmodule Natsbeam.NKeysTest do
  use ExUnit.Case, async: true
  alias Natsbeam.NKeys

  # Pair generated by the reference `nk` tool.
  @seed "SUADNZFZIESATWHBQDHXXU3BX4ENHAVXRACJX47DZN2KQTP4DAM5QCYHAE"
  @pub "UBWWOGEOBPBB2WGXNOOYEKWSCVEFN2W52ZXZP465MRJ3OTQ3M64VHCGZ"

  test "derives the same public key as nk" do
    assert {:ok, @pub} = NKeys.public_from_seed(@seed)
    assert {:ok, :user, _} = NKeys.decode_seed(@seed)
    assert {:ok, :user, _} = NKeys.decode(@pub)
  end

  test "round-trips generated keys of each type and signs/verifies" do
    for type <- [:user, :account, :operator, :server, :cluster] do
      {seed, pub} = NKeys.generate(type)
      assert {:ok, ^pub} = NKeys.public_from_seed(seed)
      assert NKeys.type_of(pub) == type
      {:ok, sig} = NKeys.sign(seed, "nonce")
      assert NKeys.verify(pub, "nonce", sig)
      refute NKeys.verify(pub, "other", sig)
    end
  end

  test "rejects corrupted keys" do
    assert {:error, _} = NKeys.decode(String.replace(@pub, "UBWW", "UBWX"))
    refute NKeys.valid_public?("not-a-key")
    refute NKeys.valid_public?(@pub, :account)
  end
end
